    int count = 0;
    for (char c : text) {
        unsigned char byte = static_cast<unsigned char>(c);
        if ((byte & 0xC0) != 0x80) {
            ++count;
        }
    }
    return count;
}

int main() {
    for (std::string_view word : {"bolt", "café", "€5", "🔧"}) {
        std::cout << word << ": " << word.size() << " bytes, "
                  << count_letters(word) << " code points\n";
    }
}

