#include <charconv>
#include <iostream>
#include <string_view>

int main() {
    std::string_view text = "12,7,3";
    const char* pos = text.data();
    const char* end = text.data() + text.size();
    int sum = 0;
    while (pos < end) {
        int value = 0;
        auto [next, err] = std::from_chars(pos, end, value);
        if (err != std::errc{}) {
            std::cout << "not a number\n";
            return 1;
        }
        sum += value;
        pos = next + 1;
    }
    std::cout << "sum: " << sum << '\n';
}

parse_machine.cpp.src:
#include <charconv>
#include <iostream>
#include <string_view>
#include <system_error>

void parse(std::string_view text) {
    int value = 0;
    auto [ptr, err] = std::from_chars(text.data(), text.data() + text.size(), value);
    std::cout << "\"" << text << "\" -> ";
    if (err == std::errc::invalid_argument) {
        std::cout << "invalid_argument";
    } else if (err == std::errc::result_out_of_range) {
        std::cout << "result_out_of_range";
    } else {
        std::cout << value << ", rest \"" << std::string_view(ptr, text.data() + text.size() - ptr) << "\"";
    }
    std::cout << '\n';
}

int main() {
    parse("42");
    parse("-7");
    parse("12abc");
    parse("abc");
    parse(" 5");
    parse("+5");
    parse("99999999999");
}

