    while (!list.empty()) {
        std::size_t comma = list.find(',');
        std::string_view item = list.substr(0, comma);
        if (comma == std::string_view::npos) {
            list.remove_prefix(list.size());
        } else {
            list.remove_prefix(comma + 1);
        }
