#include <iostream>
#include <vector>

double average(const std::vector<int>& psi) {
    int total = 0;
    for (int p : psi) {
        total += p;
    }
    return total / psi.size();
}

int main() {
    std::vector<int> psi{30, 32, 31, 32};
    std::cout << "average: " << average(psi) << '\n';
}

